fn total_cents(prices: &[i64], discount_factors: &[f64]) -> i64 {
    let sum: i64 = prices.iter().sum();
    let factor = discount_factors.iter().product::<f64>();
    ((sum as f64 * (1.0 + factor)) as i64).max(0)
}

#[test]
fn refuses_negative_discounts() {
    assert_eq!(total_cents(&[1000], &[-2.0]), 0);
}
